        mallory.arm(m); // front-run
        ok = _try(limit - INTRINSIC);
        endsAfter = auction.endsAt();
        if (!ok) {
            require(auction.highestBidder() == address(mallory), "leader changed");
            require(endsAfter == endsBefore, "close moved");
            require(ALICE.balance == 10 ether, "value not returned");
