        vmx.cool(address(mallory));
        // Even the bare estimate with no wallet buffer at all still lands.
        assertTrue(aliceBids(cheap));
        assertEq(auction.highestBidder(), ALICE);
        assertEq(auction.refunds(address(mallory)), MALLORY_BID);
