// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";

/// @dev The searcher's contract: one call ladders self-outbids up to the highest price that the
///      victim's pending bid still validly beats.
contract Ladder {
    KilimAuction public immutable auction;
    address public immutable owner;
    uint256 public bids;

    constructor(KilimAuction a) payable {
        auction = a;
        owner = msg.sender;
    }

    function run(uint256 victimAmount, uint256 bps) external {
        require(msg.sender == owner, "owner");
        while (true) {
            uint256 next = auction.minimumBid();
            // Stop while the victim's amount is still >= the minimum bid after ours.
            uint256 after_ = next + (next * bps + 9999) / 10000;
            after_ = ((after_ + 0.001 ether - 1) / 0.001 ether) * 0.001 ether;
            if (after_ > victimAmount) break;
            auction.bid{value: next}(next, 0, 0);
            ++bids;
        }
    }

    function sweep() external {
        require(msg.sender == owner, "owner");
        (bool ok,) = owner.call{value: address(this).balance}("");
        require(ok, "sweep");
    }

    function claim(uint256 quantity) external {
        require(msg.sender == owner, "owner");
        auction.claimSymbols(quantity, owner);
    }

    receive() external payable {}
}

