        for (uint160 i = 1000; i < 1100; ++i) {
            vm.deal(address(i), 0.01 ether);
            vm.prank(address(i));
            auction.register();
        }
        // Current top bid: 1 ETH by Bob.
        vm.deal(BOB, 1 ether);
        vm.prank(BOB);
        auction.bid{value: 1 ether}(1 ether, 1000, 0);
        vm.deal(ALICE, 3 ether);
        vm.deal(SEARCHER, 6 ether);
    }

    function testLadderInFrontOfJumpBidIsRiskFree() public {
