        (bool okEoa,, uint256 eoaUsed) = sponsored(user, sig(KEY, user), 5_000_000);
        assertTrue(okEoa);
        emit Measured("EOA registerFor (execution only)", eoaUsed);
        assertTrue(eoaUsed < 90_000);

