    /// that supporter is NOT registered.
    function testRaceAtTheCapLeavesSupporterOut() public {
        for (uint160 i = 1000; i < 1099; ++i) {
            vm.deal(address(i), 0.01 ether);
            vm.prank(address(i));
            auction.register();
        }
        bytes memory s = sig(KEY, user);
        vm.deal(BOB, 0.01 ether);
        vm.prank(BOB);
        auction.register(); // the 100th
        (bool ok, bytes memory ret,) = sponsored(user, s, RELAYER_GAS);
        assertTrue(!ok);
        assertEq(bytes32(ret), bytes32(ERC20EnglishAuction.RegistrationClosed.selector));
        assertTrue(!auction.registered(user));
