    /// One 0.01 ETH rotated through 100 fresh EOAs: the sponsor pays for all 100 registrations and
    /// the 100-wallet gate opens with a single wallet's worth of capital.
    function testOneBalanceRotatedThroughHundredSponsoredSybils() public {
        address prev = pvm.addr(5000);
        vm.deal(prev, 0.01 ether);
        uint256 sponsorGas;
        for (uint256 k = 5000; k < 5100; ++k) {
            address a = pvm.addr(k);
            if (a != prev) {
                vm.prank(prev);
                (bool sent,) = a.call{value: 0.01 ether}("");
                assertTrue(sent);
                prev = a;
            }
            (bool ok,, uint256 used) = sponsored(a, sig(k, a), RELAYER_GAS);
            assertTrue(ok);
            sponsorGas += used;
        }
        emit Measured("sponsor execution gas for 100 sybils", sponsorGas);
        assertEq(auction.registrationCount(), 100);
        // Total ETH across all 100 "registered" wallets is still one registration balance.
        uint256 total;
        for (uint256 k = 5000; k < 5100; ++k) total += pvm.addr(k).balance;
        assertEq(total, 0.01 ether);
        // The gate is now shut for a real supporter, sponsored or not...
        (bool late, bytes memory ret,) = sponsored(user, sig(KEY, user), RELAYER_GAS);
        assertTrue(!late);
        assertEq(bytes32(ret), bytes32(ERC20EnglishAuction.RegistrationClosed.selector));
        // ...but bidding is open to anyone (bid() does not require the bidder to be registered).
        vm.deal(ALICE, 0.01 ether);
        vm.prank(ALICE);
        auction.bid{value: 0.01 ether}(0.01 ether, 10, 0);
        assertEq(auction.highestBidder(), ALICE);
    }
