            return(0, returndatasize())
        }
    }
}

contract F14Test is TestBase {
    event log_named_uint(string key, uint256 value);

    VmF14 internal constant vmd = VmF14(address(uint160(uint256(keccak256("hevm cheat code")))));
    address internal constant DEPLOYER = address(0xD3910);
    string internal constant STORE = "../onchain/build";
    address internal constant ARTIST = 0xd6647Eeec0c8D810C546f2ab8e025D4664d833Ac;
    uint256 internal constant DECIDED_MOTIFS = 1024; // launch/DECISIONS.md
    uint256 internal constant MASTERPIECE_CEILING = 24_000_000; // test/render/RenderGasLimits.t.sol
    uint256 internal constant HARD_CEILING = 45_000_000; // test/render/RenderGasLimits.t.sol

    DeployHarnessF14 internal script;
    string internal manifest;

    function setUp() public {
        script = new DeployHarnessF14();
        manifest = vmd.readFile(string.concat(STORE, "/manifest.json"));
        vm.warp(1_800_000_000);
    }

    /// @dev Exactly the decided launch settings, on whatever chain is current, with the store on disk.
    function _launchConfig() internal view returns (DeployKilim.Config memory c) {
        c.chainId = block.chainid;
        c.store = STORE;
        c.deployer = DEPLOYER;
        c.deployerNonce = vmd.getNonce(DEPLOYER);
        c.motifCount = vmd.parseJsonUint(manifest, ".motifCount");
        c.geometryHash = vmd.parseJsonBytes32(manifest, ".hashes.geometryHash");
        c.indexHash = vmd.parseJsonBytes32(manifest, ".hashes.indexHash");
        c.pageHash = vmd.parseJsonBytes32(manifest, ".hashes.pageHash");
        c.tokenDecimals = 18;
        c.minLeadSeconds = 1 days;
        c.auction.paymentToken = address(0);
        c.auction.treasury = ARTIST;
        c.auction.collectionOwner = ARTIST;
        c.auction.startsAt = uint64(block.timestamp + 2 days);
        c.auction.duration = 86_400;
        c.auction.extensionWindow = 600;
        c.auction.incrementBps = 1000;
        c.auction.reservePrice = 0.01 ether;
        c.auction.symbolCap = 1_000_000;
        c.auction.maxSymbolsPerBid = 1_000_000;
        c.auction.maxCells = 256;
    }

    function _gas(address target, bytes memory data) internal view returns (uint256 used) {
        bool ok;
        assembly {
            let g := gas()
            ok := staticcall(gas(), target, add(data, 32), mload(data), 0, 0)
            used := sub(g, gas())
        }
        require(ok, "call reverted");
        used += 21_000 + 16 * data.length;
    }

    /// Part 1: both phases, run on chain 1 from the build on disk, pass every guard and fix 812 motifs,
    /// although the decision is 1,024. The Sepolia template names the same 812 pack.
    function testMainnetAcceptsThe812PackAlthoughTheDecisionIs1024() public {
        vmd.chainId(1);
        DeployKilim.Config memory c = _launchConfig();
        assertEq(c.chainId, 1);
        KilimRenderer renderer = script.deployStore(c); // runStore: not refused
        c.rendererHash = address(renderer).codehash;
        c.deployerNonce = vmd.getNonce(DEPLOYER);
        KilimAuction auction = script.deployAuction(c, renderer); // runAuction: not refused
        Kilim nft = auction.collection();

        assertEq(block.chainid, 1);
        assertEq(nft.motifCount(), 812);
        assertTrue(nft.motifCount() != DECIDED_MOTIFS);
        assertEq(renderer.motifCount(), 812);
        // The store on disk and the Sepolia template are the 812 pack.
        assertEq(vmd.parseJsonUint(manifest, ".motifCount"), 812);
        string memory sepolia = vmd.readFile("deploy/sepolia.example.json");
        assertEq(vmd.parseJsonUint(sepolia, ".expected.motifCount"), 812);
        assertEq(
            vmd.parseJsonBytes32(sepolia, ".expected.geometryHash"),
            vmd.parseJsonBytes32(manifest, ".hashes.geometryHash")
        );
    }

    /// Part 2: the script's renderer check accepts a renderer whose 1/1 read costs far more than every
    /// published ceiling, because it compares answers and never measures gas.
    function testRendererCheckHasNoReadGasCeiling() public {
        DeployKilim.Config memory c = _launchConfig();
        KilimRenderer renderer = script.deployStore(c);

        bytes memory call_ = abi.encodeCall(KilimRenderer.masterpieceURI, ());
        uint256 real = _gas(address(renderer), call_);
        emit log_named_uint("masterpieceURI gas, 812 pack on disk", real);
        emit log_named_uint("headroom to the 24M target", MASTERPIECE_CEILING - real);
        assertTrue(real < MASTERPIECE_CEILING);
        assertTrue(MASTERPIECE_CEILING - real < 2_000_000); // under 2M of room left today

        HeavyRendererF14 heavy = new HeavyRendererF14(address(renderer), 40_000_000);
        uint256 heavyGas = _gas(address(heavy), call_);
        emit log_named_uint("masterpieceURI gas, heavier stand-in", heavyGas);
        assertTrue(heavyGas > MASTERPIECE_CEILING);
        assertTrue(heavyGas > HARD_CEILING); // over even the 45M "anything" cap

        // The script's own check, unchanged: no Refused.
        script.checkRendererAt(c, address(heavy));
        // And the real renderer passes the same call, so the harness is checking what the script checks.
        script.checkRendererAt(c, address(renderer));
    }
}
```

