// SPDX-License-Identifier: MIT
pragma solidity 0.8.37;

import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {ERC20EnglishAuction} from "../../src/auction/ERC20EnglishAuction.sol";

/// @dev A contract bidder: can refuse ETH, has no onERC721Received (so a pushed 1/1 is rejected).
contract F15Wallet {
    bool public rejectEth = true;
    function setReject(bool flag) external { rejectEth = flag; }
    function call(address target, uint256 value, bytes calldata data) external returns (bytes memory) {
        (bool ok, bytes memory result) = target.call{value: value}(data);
        if (!ok) assembly ("memory-safe") { revert(add(result, 32), mload(result)) }
        return result;
    }
    receive() external payable { require(!rejectEth, "no ETH"); }
}

/// @dev Sends its balance to a target that cannot refuse it.
contract F15Force {
    constructor(address payable target) payable { selfdestruct(target); }
}

contract F15Test is TestBase {
    KilimAuction auction;
    uint256 constant E = 0.001 ether;

    function setUp() public {
        KilimAuction.Config memory c = config(address(0));
        c.reservePrice = 0.01 ether;
        c.duration = 1 days;
        c.incrementBps = 1000;
        auction = new KilimAuction(c);
        vm.warp(c.startsAt);
        vm.deal(ALICE, 10 ether);
        vm.deal(BOB, 10 ether);
        vm.deal(CAROL, 10 ether);
    }

    function registerN(uint160 n) internal {
        for (uint160 i = 1000; i < 1000 + n; ++i) {
            vm.deal(address(i), 1 ether);
            vm.prank(address(i));
            auction.register();
        }
    }

    function bidAs(address user, uint256 amount) internal {
        vm.prank(user);
        auction.bid{value: amount}(amount, 0, 0);
    }

    function walletBid(F15Wallet w, uint256 amount) internal {
        vm.deal(address(w), address(w).balance + amount);
        w.call(address(auction), amount, abi.encodeCall(auction.bid, (amount, 0, 0)));
    }

    function testRegisteredWalletCannotBidAt99() public {
        registerN(99);
        assertTrue(auction.registered(address(1000)));
        vm.expectRevert(ERC20EnglishAuction.RegistrationIncomplete.selector);
        vm.prank(address(1000));
        auction.bid{value: 10 * E}(10 * E, 0, 0);
        assertEq(address(auction).balance, 0);
    }

    function testDeferredRefundsAccumulateAndSurviveSettlement() public {
        registerN(100);
        F15Wallet w = new F15Wallet();
        walletBid(w, 10 * E);
        bidAs(ALICE, 11 * E); // refund 0.010 to w deferred
        assertEq(auction.refunds(address(w)), 10 * E);
        walletBid(w, 13 * E); // ALICE refunded directly
        assertEq(ALICE.balance, 10 ether);
        bidAs(BOB, 15 * E); // refund 0.013 to w deferred: must ADD
        assertEq(auction.refunds(address(w)), 23 * E);
        assertEq(auction.refundLiability(), 23 * E);
        assertEq(address(auction).balance, 38 * E);
        assertEq(auction.liabilities(), 38 * E);

        new F15Force{value: 1 ether}(payable(address(auction))); // forced ETH
        assertEq(address(auction).balance, 38 * E + 1 ether);

        vm.warp(auction.endsAt());
        auction.settle();
        assertEq(auction.proceedsDue(), 15 * E); // not address(this).balance
        assertEq(auction.liabilities(), 38 * E);

        uint256 before = TREASURY.balance;
        vm.prank(TREASURY);
        auction.withdrawProceeds(TREASURY);
        assertEq(TREASURY.balance - before, 15 * E);

        w.call(address(auction), 0, abi.encodeCall(auction.withdrawRefund, (CAROL)));
        assertEq(CAROL.balance, 10 ether + 23 * E);
        assertEq(auction.refundLiability(), 0);
        assertEq(auction.liabilities(), 0);
        assertEq(address(auction).balance, 1 ether); // only the forced ETH remains
        assertEq(auction.collection().ownerOf(1), BOB); // EOA winner got the 1/1 pushed
        assertTrue(auction.prizeClaimed());
    }

    function testExtensionCloseAndEarlySettle() public {
        registerN(100);
        bidAs(ALICE, 10 * E);
        uint64 end0 = auction.endsAt();
        assertEq(end0, block.timestamp + 1 days);
        vm.warp(end0 - 11 minutes); // outside the window: no extension
        bidAs(BOB, 11 * E);
        assertEq(auction.endsAt(), end0);
        vm.warp(end0 - 1); // inside the window
        bidAs(ALICE, 13 * E);
        assertEq(auction.endsAt(), uint64(block.timestamp + 10 minutes));
        uint64 end1 = auction.endsAt();
        vm.warp(end1 - 1);
        vm.expectRevert(ERC20EnglishAuction.AuctionNotEnded.selector);
        auction.settle();
        vm.warp(end1);
        vm.expectRevert(ERC20EnglishAuction.AuctionNotOpen.selector);
        vm.prank(BOB);
        auction.bid{value: 15 * E}(15 * E, 0, 0);
        assertEq(auction.highestBidder(), ALICE);
        auction.settle();
        assertEq(auction.proceedsDue(), 13 * E);
    }

    function testIncrementAndUnit() public {
        registerN(100);
        vm.expectRevert(ERC20EnglishAuction.NonWholeUnitBid.selector);
        vm.prank(ALICE);
        auction.bid{value: 10 * E + 1}(10 * E + 1, 0, 0);
        bidAs(ALICE, 20 * E);
        assertEq(auction.minimumBid(), 22 * E);
        vm.expectRevert(abi.encodeWithSelector(ERC20EnglishAuction.BidTooLow.selector, 22 * E));
        vm.prank(BOB);
        auction.bid{value: 21 * E}(21 * E, 0, 0);
        vm.expectRevert(ERC20EnglishAuction.NonWholeUnitBid.selector);
        vm.prank(BOB);
        auction.bid{value: 22 * E + 1}(22 * E + 1, 0, 0);
        bidAs(BOB, 22 * E);
        assertEq(auction.highestBidder(), BOB);
        assertEq(ALICE.balance, 10 ether);
    }

    function testTreasuryCannotBidEth() public {
        registerN(100);
        vm.deal(TREASURY, 1 ether);
        vm.expectRevert(ERC20EnglishAuction.TreasuryCannotBid.selector);
        vm.prank(TREASURY);
        auction.bid{value: 10 * E}(10 * E, 0, 0);
    }

    function testRejectingWinnerThenClaimPrize() public {
        registerN(100);
        F15Wallet w = new F15Wallet();
        walletBid(w, 10 * E);
        vm.warp(auction.endsAt());
        auction.settle();
        assertTrue(auction.settled());
        assertTrue(!auction.prizeClaimed());
        vm.expectRevert(ERC20EnglishAuction.Unauthorized.selector);
        vm.prank(BOB);
        auction.claimPrize(BOB);
        vm.expectRevert(ERC20EnglishAuction.Unauthorized.selector);
        vm.prank(TREASURY);
        auction.claimPrize(TREASURY);
        w.call(address(auction), 0, abi.encodeCall(auction.claimPrize, (CAROL)));
        assertEq(auction.collection().ownerOf(1), CAROL);
        vm.expectRevert(KilimAuction.PrizeAlreadyClaimed.selector);
        w.call(address(auction), 0, abi.encodeCall(auction.claimPrize, (CAROL)));
        vm.prank(TREASURY);
        auction.withdrawProceeds(TREASURY);
        assertEq(address(auction).balance, 0);
    }
}
```

