interface SigningVmF16 {
    function addr(uint256) external returns (address);
    function sign(uint256, bytes32) external returns (uint8, bytes32, bytes32);
}

/// F-16. These are the three guards in _register (ERC20EnglishAuction.sol:147-154) that no test in
/// the existing suite exercises. Each test passes on the on-disk code and FAILS on the matching mutant.
contract F16Test is TestBase {
    SigningVmF16 private signer = SigningVmF16(address(vm));
    uint256 private constant KEY = 0xF16;
    uint256 private constant TREASURY_KEY = 0x7EA5;

    function _eth() private view returns (KilimAuction.Config memory c) {
        c = config(address(0));
        c.reservePrice = 0.01 ether;
    }

    function _sig(uint256 key, bytes32 digest) private returns (bytes memory) {
        (uint8 v, bytes32 r, bytes32 s) = signer.sign(key, digest);
        return abi.encodePacked(r, s, v);
    }

    // Mutant 1: drop `block.timestamp < startsAt`.
    function testRegisterRefusedOneSecondBeforeStartsAt() public {
        KilimAuction.Config memory c = _eth();
        KilimAuction auction = new KilimAuction(c);
