        KilimAuction.Config memory c = _eth();
        KilimAuction auction = new KilimAuction(c);
        address user = signer.addr(KEY);
        vm.deal(user, 0.01 ether);
        uint256 deadline = c.startsAt + 1 hours;
        bytes memory sig = _sig(KEY, auction.registrationDigest(user, deadline));
        vm.warp(c.startsAt - 1);
        vm.expectRevert(ERC20EnglishAuction.RegistrationClosed.selector);
        vm.prank(BOB);
        auction.registerFor(user, deadline, sig);
        assertEq(auction.registrationCount(), 0);
        vm.warp(c.startsAt);
        vm.prank(BOB);
        auction.registerFor(user, deadline, sig);
