import {TestBase} from "../TestBase.sol";
import {KilimAuction} from "../../src/KilimAuction.sol";
import {ERC20EnglishAuction} from "../../src/auction/ERC20EnglishAuction.sol";
// Byte-for-byte copies of the on-disk sources with ONE string changed each (see the diff in the report).
import {KilimAuction as MutName} from "./f18m/name/src/KilimAuction.sol"; // EIP712("Kilim Registrations", "1")
import {KilimAuction as MutVersion} from "./f18m/version/src/KilimAuction.sol"; // EIP712("Kilim Registration", "2")
import {KilimAuction as MutType} from "./f18m/type/src/KilimAuction.sol"; // "Register(address account,uint256 expiry)"

interface SigningVm {
    function addr(uint256) external returns (address);
    function sign(uint256, bytes32) external returns (uint8, bytes32, bytes32);
}

interface IAuc {
    function registrationDigest(address, uint256) external view returns (bytes32);
    function registerFor(address, uint256, bytes calldata) external;
    function registered(address) external view returns (bool);
    function eip712Domain()
        external
        view
        returns (bytes1, string memory, string memory, uint256, address, bytes32, uint256[] memory);
}

contract F18Test is TestBase {
    SigningVm private signer = SigningVm(address(vm));
    uint256 private constant KEY_A = 123456;
    uint256 private constant KEY_B = 654321;
    address private userA;
    address private userB;
    uint256 private deadline;
    KilimAuction.Config private c;

    function setUp() public {
        c = config(address(0));
        c.reservePrice = 0.01 ether;
        userA = signer.addr(KEY_A);
        userB = signer.addr(KEY_B);
        vm.deal(userA, 0.01 ether);
        vm.deal(userB, 0.01 ether);
    }

    /// @dev What a wallet computes for eth_signTypedData_v4 with the typed data hard-coded in
    ///      site/chain.js:1020-1028. Built without calling the contract.
    function siteDigest(address verifyingContract, address wallet, uint256 deadline_)
        private
        view
        returns (bytes32)
    {
        bytes32 domain = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256("Kilim Registration"),
                keccak256("1"),
                block.chainid,
                verifyingContract
            )
        );
        bytes32 structHash =
            keccak256(abi.encode(keccak256("Register(address wallet,uint256 deadline)"), wallet, deadline_));
        return keccak256(abi.encodePacked("\x19\x01", domain, structHash));
    }

    function sig(uint256 key, bytes32 digest) private returns (bytes memory) {
        (uint8 v, bytes32 r, bytes32 s) = signer.sign(key, digest);
        return abi.encodePacked(r, s, v);
    }

    function start() private {
        vm.warp(c.startsAt);
        deadline = block.timestamp + 15 minutes;
    }

    /// Control: the contract on disk agrees with the site today.
    function testOnDiskContractMatchesSiteDomain() public {
        IAuc a = IAuc(address(new KilimAuction(c)));
        start();
        assertEq(a.registrationDigest(userA, deadline), siteDigest(address(a), userA, deadline));
        (, string memory name, string memory version, uint256 chainId, address verifying,,) = a.eip712Domain();
        assertEq(keccak256(bytes(name)), keccak256("Kilim Registration"));
        assertEq(keccak256(bytes(version)), keccak256("1"));
        assertEq(chainId, block.chainid);
        assertEq(verifying, address(a));
        a.registerFor(userA, deadline, sig(KEY_A, siteDigest(address(a), userA, deadline)));
        assertTrue(a.registered(userA));
    }

    /// For a mutant: (1) the style used by every existing Foundry test (sign whatever the contract
    /// returns) still succeeds, and (2) the signature a real wallet produces from the site's typed
    /// data is rejected.
    function mutantSurvivesButSiteSignatureDies(IAuc a) private {
        start();
        bytes32 site = siteDigest(address(a), userA, deadline);
        assertTrue(a.registrationDigest(userA, deadline) != site);

