        bytes memory siteSig = sig(KEY_A, site);
        vm.expectRevert(ERC20EnglishAuction.InvalidRegistrationSignature.selector);
        a.registerFor(userA, deadline, siteSig);
        assertTrue(!a.registered(userA));

        // (1) self-consistent test style -> green
        bytes memory selfSig = sig(KEY_B, a.registrationDigest(userB, deadline));
        a.registerFor(userB, deadline, selfSig);
        assertTrue(a.registered(userB));
    }

    function testMutantNameSurvives() public {
        mutantSurvivesButSiteSignatureDies(IAuc(address(new MutName(abi.decode(abi.encode(c), (MutName.Config))))));
    }

    function testMutantVersionSurvives() public {
        mutantSurvivesButSiteSignatureDies(
